   try {
     parsed = load(frontmatter);
   } catch (err) {
     throw new Error(`Failed to parse frontmatter as yaml: ${err}`);
   }
   if (typeof parsed !== 'object' || parsed === null) {
     throw new Error(
       `Expected frontmatter yaml to be an object but found:\n${JSON.stringify(parsed)}`
