1. import React, { ElementType, ReactNode } from 'react';
2. import { RenderableTreeNodes, Scalar, RenderableTreeNode, Tag } from '@markdoc/markdoc';
3. import { Code, InlineCode } from './primitives/Code';
4. import { Heading } from './docs/Heading';
5. import { RelatedContent } from './RelatedContent';
6. import { Well } from './primitives/Well';
7. import { YouTubeEmbed } from './primitives/YouTubeEmbed';
8. import { Emoji } from './primitives/Emoji';
9. import { ComingSoon } from './docs/ComingSoon';
10. 
11. const renderers: Record<string, ElementType> = {
12.   code: InlineCode,
13.   CodeBlock(props: { content: string; language: string }) {
14.     return (
15.       <pre>
16.         <Code className={`language-${props.language}`}>{props.content}</Code>
17.       </pre>
18.     );
19.   },
20.   ComingSoon,
21.   Emoji,
22.   Well,
23.   YouTubeEmbed,
24.   RelatedContent,
25.   Heading(props: { children: ReactNode; level: 1 | 2 | 3 | 4 | 5 | 6; id: string }) {
26.     return <Heading {...props} />;
27.   },
28. };
29. 
30. // inlined from markdoc because
31. // - it's so trivial to write
32. // - the markdoc implementation was doing weird things with the components(you couldn't override built in tags)
33. // - to avoid bundling all of markdoc on the front-end
34. export function Markdoc(props: { content: RenderableTreeNodes }) {
35.   function deepRender(value: any): any {
36.     if (value == null || typeof value !== 'object') return value;
37. 
38.     if (Array.isArray(value)) return value.map(item => deepRender(item));
39. 
40.     if (value.$$mdtype === 'Tag') return render(value);
41. 
42.     if (typeof value !== 'object') return value;
43. 
44.     const output: Record<string, Scalar> = {};
45.     for (const [k, v] of Object.entries(value)) output[k] = deepRender(v);
46.     return output;
47.   }
48. 
49.   function render(node: RenderableTreeNodes): ReactNode {
50.     if (Array.isArray(node)) {
51.       return React.createElement(React.Fragment, null, ...node.map(render));
52.     }
53. 
54.     if (node === null || typeof node !== 'object') return node;
55. 
56.     const { name, attributes: { class: className, ...attrs } = {}, children = [] } = node;
57. 
58.     if (className) attrs.className = className;
59.     let elementType = renderers[name];
60.     if (elementType === undefined) {
61.       if (name[0].toLowerCase() === name[0]) {
62.         elementType = name as ElementType;
63.       } else {
64.         throw new Error(`No renderer provided for element type: ${name}`);
65.       }
66.     }
67. 
68.     return React.createElement(
69.       elementType,
70.       Object.keys(attrs).length == 0 ? null : deepRender(attrs),
71.       ...children.map(render)
72.     );
73.   }
74. 
75.   return render(props.content) as JSX.Element;
76. }
77. 
78. export type HeadingType = {
79.   id: string;
80.   depth: number;
81.   label: string;
82. };
83. 
84. export function extractHeadings(content: Tag): HeadingType[] {
85.   const headings: HeadingType[] = [];
86.   for (const child of content.children) {
87.     if (typeof child !== 'string' && child !== null && child.name === 'Heading') {
88.       headings.push({
89.         id: child.attributes.id,
90.         depth: child.attributes.level,
91.         label: stringifyDocContent(child),
92.       });
93.     }
94.   }
95.   return headings;
96. }
97. 
98. function stringifyDocContent(node: RenderableTreeNode): string {
