1. // @markdoc/markdoc's declaration files depend on these global types
2. import type {} from '@markdoc/markdoc/global';
3. import fs from 'fs/promises';
4. import Markdoc, { Config, Tag, ValidateError } from '@markdoc/markdoc';
5. import { isNonEmptyArray } from 'emery/guards';
6. import { assert } from 'emery/assertions';
7. import { load } from 'js-yaml';
8. import { baseMarkdocConfig } from './config';
9. import { showNextReleaseWithoutReplacement } from './show-next-release';
10. 
11. export function printValidationError(error: ValidateError) {
12.   const location = error.error.location || error.location;
13.   // the filepath is intentionally duplicated here so that there is one thing you can copy to refer to the error position
14.   return `${location?.file ?? '(unknown file)'}:${
15.     // the +1 is because location.start.line is 0-based
16.     // but tools generally use 1-based line numbers
17.     location?.start.line !== undefined ? location.start.line + 1 : '(unknown line)'
18.   }${location?.start.character !== undefined ? `:${location.start.character}` : ''}: ${
19.     error.error.message
20.   }`;
21. }
22. 
23. class MarkdocValidationFailure extends Error {
24.   constructor(errors: [ValidateError, ...ValidateError[]], errorReportingFilepath: string) {
25.     super();
26.     this.name = 'MarkdocValidationFailure';
27.     // you see the stacktrace and a bunch of other stuff from Next when seeing the errors here
28.     // so this separator makes it easier to find the actual problem
29.     const separator = `⎯⎯⎯⎯⎯⎯⎯⎯⎯⎯⎯⎯⎯⎯`;
30.     this.message = `Errors in ${errorReportingFilepath}:\n${separator}\n${errors
31.       .map(error => printValidationError(error))
32.       .join('\n')}\n${separator}`;
33.   }
34. }
35. 
36. export type DocsContent = {
37.   content: Tag;
38.   title: string;
39.   description: string;
40. };
41. 
42. export type BlogContent = BlogFrontmatter & {
43.   content: Tag;
44. };
45. 
46. export async function readBlogContent(filepath: string): Promise<BlogContent> {
47.   let content = await fs.readFile(filepath, 'utf8');
48.   const frontmatter = extractBlogFrontmatter(content);
49.   return { content: transformContent(`docs/${filepath}`, content), ...frontmatter };
50. }
51. 
52. export async function readDocsContent(filepath: string): Promise<DocsContent> {
53.   let content = await fs.readFile(filepath, 'utf8');
54.   const frontmatter = extractDocsFrontmatter(content);
55.   return { content: transformContent(`docs/${filepath}`, content), ...frontmatter };
56. }
57. 
58. const markdocConfig: Config = {
59.   ...baseMarkdocConfig,
60.   variables: {
61.     nextRelease: showNextReleaseWithoutReplacement,
62.   },
63. };
64. 
65. export function transformContent(errorReportingFilepath: string, content: string): Tag {
66.   const node = Markdoc.parse(content, errorReportingFilepath);
67.   const errors = Markdoc.validate(node, markdocConfig);
68.   if (isNonEmptyArray(errors)) {
69.     throw new MarkdocValidationFailure(errors, errorReportingFilepath);
70.   }
71.   const renderableNode = Markdoc.transform(node, markdocConfig);
72. 
73.   assert(renderableNode !== null && typeof renderableNode !== 'string');
74. 
75.   // Next is annoying about not plain objects
76.   return JSON.parse(JSON.stringify(renderableNode)) as typeof renderableNode;
77. }
78. 
79. const frontMatterPattern = /^---[\s]+([\s\S]*?)[\s]+---/;
80. 
81. export function extractDocsFrontmatter(content: string): {
82.   title: string;
83.   description: string;
84. } {
85.   const match = frontMatterPattern.exec(content);
86.   if (!match) {
87.     throw new Error('Expected document to contain frontmatter with a title and description');
88.   }
89.   const frontmatter = match[1];
90.   let parsed;
91.   try {
92.     parsed = load(frontmatter);
93.   } catch (err) {
94.     throw new Error(`Failed to parse frontmatter as yaml: ${err}`);
95.   }
96.   if (typeof parsed !== 'object' || parsed === null) {
97.     throw new Error(
98.       `Expected frontmatter yaml to be an object but found:\n${JSON.stringify(parsed)}`
99.     );
100.   }
101.   let obj = parsed as Record<string, unknown>;
102.   if (typeof obj.title !== 'string') {
103.     throw new Error(`Expected frontmatter to contain a title`);
104.   }
105.   if (typeof obj.description !== 'string') {
106.     throw new Error(`Expected frontmatter to contain a description`);
107.   }
108. 
109.   return {
110.     title: obj.title,
111.     description: obj.description,
112.   };
113. }
114. 
115. export type BlogFrontmatter = {
116.   title: string;
117.   description: string;
118.   publishDate: string;
119.   authorName: string;
120.   authorHandle?: string;
121.   metaImageUrl?: string;
122. };
123. 
124. export function extractBlogFrontmatter(content: string): BlogFrontmatter {
125.   const match = frontMatterPattern.exec(content);
126.   if (!match) {
127.     throw new Error(
128.       'Expected post to contain frontmatter with a title, description and publishDate'
129.     );
130.   }
131.   const frontmatter = match[1];
132.   let parsed;
133.   try {
134.     parsed = load(frontmatter);
135.   } catch (err) {
136.     throw new Error(`Failed to parse frontmatter as yaml: ${err}`);
137.   }
138.   if (typeof parsed !== 'object' || parsed === null) {
139.     throw new Error(
140.       `Expected frontmatter yaml to be an object but found:\n${JSON.stringify(parsed)}`
141.     );
142.   }
143.   let obj = parsed as Record<string, unknown>;
144.   if (typeof obj.title !== 'string') {
145.     throw new Error(`Expected frontmatter to contain title`);
146.   }
147.   if (typeof obj.description !== 'string') {
148.     throw new Error(`Expected frontmatter to contain description`);
149.   }
150.   if (typeof obj.publishDate !== 'string') {
151.     throw new Error(`Expected frontmatter to contain publishDate`);
152.   }
153.   if (typeof obj.authorName !== 'string') {
154.     throw new Error(`Expected frontmatter to contain authorName`);
155.   }
156. 
157.   if (typeof obj.authorHandle !== 'string' && typeof obj.authorHandle !== 'undefined') {
158.     throw new Error(`Expected frontmatter to contain authorHandle`);
159.   }
160. 
161.   if (typeof obj.metaImageUrl !== 'string' && typeof obj.metaImageUrl !== 'undefined') {
162.     throw new Error(`Expected frontmatter to contain metaImageUrl`);
163.   }
164. 
165.   return {
166.     title: obj.title,
167.     description: obj.description,
168.     publishDate: obj.publishDate,
169.     authorName: obj.authorName,
170.     authorHandle: obj.authorHandle,
171.     metaImageUrl: obj.metaImageUrl,
172.   };
173. }
